int solution(int init[], int init_len, int presses[], int presses_len) {
    int desk[101] = {0};
    for (int i = 1; i <= init_len; i++) {
        desk[i] = init[i - 1];
    }
    for (int p = 0; p < presses_len; p++) {
        int k = presses[p];
        for (int d = 1; d <= k; d++) {
            if (k % d == 0) {
                desk[d] = 1 - desk[k];
            }
        }
    }
    int count = 0;
    for (int i = 1; i <= init_len; i++) {
        if (desk[i] == 1) count++;
    }
    return count;
}

