void flip(int lamp[], int idx) {
    lamp[idx] = 1 - lamp[idx];
}

int* solution(int n, int cmds[], int cmds_len) {
    int lamp[101] = {0};
    for (int r = 0; r < cmds_len; r++) {
        int k = cmds[r];
        if (k == 0) continue;
        int step = (k > 0) ? k : -k;
        for (int m = step; m <= n; m += step) {
            if (k > 0) flip(lamp, m);
            else flip(lamp, n - m);
        }
    }
    int* answer = (int*)malloc(sizeof(int) * 2);
    answer[0] = -1;
    answer[1] = -1;
    for (int i = 1; i <= n; i++) {
        if (lamp[i] == 1) {
            answer[0] = i;
            break;
        }
    }
    for (int i = n; i >= 1; i--) {
        if (lamp[i] == 1) {
            answer[1] = i;
            break;
        }
    }
    return answer;
}

